import {readFile,writeFile,readdir} from 'node:fs/promises';
import {resolve} from 'node:path';
const root=resolve('output/financeiro-velocidade-20261117');
const ler=async fase=>JSON.parse(await readFile(resolve(root,fase,'resultados.json'),'utf8'));
const antes=await ler('antes-26'),depois=await ler('depois-otimizado-26');
const buildEntrega=JSON.parse(await readFile(resolve(root,'build-final3','health.json'),'utf8'));
const extras=[];for(const dir of await readdir(root,{withFileTypes:true}))if(dir.isDirectory()&&!['antes-26','depois-otimizado-26','baseline-src','build-depois','build-final'].includes(dir.name)){try{const dados=await ler(dir.name);if(dados.fase&&Array.isArray(dados.verificacoes))extras.push({pasta:dir.name,...dados})}catch{}}
const fmt=n=>Number(n).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const q=(arr,p)=>{const a=[...arr].sort((x,y)=>x-y);return a[Math.max(0,Math.ceil(a.length*p)-1)]??0};
const stats=r=>({n:r.length,mediana:q(r.map(x=>x.segundos),.5),p95:q(r.map(x=>x.segundos),.95),max:q(r.map(x=>x.segundos),1),cliques:q(r.map(x=>x.cliques),.5),consultas:q(r.map(x=>x.consultas),.5)});
// A lista permanece visível na nova versão. O filtro pode terminar durante o
// início da edição; somar o par evita atribuir essa espera à etapa errada.
function processos(rows){
 const dupla=['Encontrar uma conta','Editar valor e vencimento'];const r=rows.filter(x=>!dupla.includes(x.nome));
 for(const a of rows.filter(x=>x.nome===dupla[0])){const b=rows.find(x=>x.nome===dupla[1]&&x.perfil===a.perfil&&x.mobile===a.mobile);if(b)r.push({...a,nome:'Encontrar e editar valor/vencimento',segundos:a.segundos+b.segundos,cliques:a.cliques+b.cliques,campos:a.campos+b.campos,consultas:a.consultas+b.consultas})}return r;
}
// Completa somente o caso interrompido antes de medir a abertura. Nenhuma
// amostra bem-sucedida é substituída por um reteste mais rápido.
const complemento=(extras.find(x=>x.pasta==='reteste-otimizado')?.resultados||[]).filter(r=>!depois.resultados.some(x=>x.perfil===r.perfil&&x.mobile===r.mobile&&x.nome===r.nome));
const depoisAnalise=[...depois.resultados,...complemento];
const ra=processos(antes.resultados),rd=processos(depoisAnalise);
const resumo=[];for(const nome of new Set(ra.map(r=>r.nome)))for(const mobile of [false,true]){const a=stats(ra.filter(r=>r.nome===nome&&r.mobile===mobile)),d=stats(rd.filter(r=>r.nome===nome&&r.mobile===mobile));resumo.push({nome,mobile,antes:a,depois:d,reducao:100*(1-d.mediana/a.mediana)})}
const linhas=resumo.map(r=>`<tr><td>${esc(r.nome)}</td><td>${r.mobile?'Celular':'Desktop'}</td><td>${r.antes.n}/${r.depois.n}</td><td>${fmt(r.antes.mediana)} → <b>${fmt(r.depois.mediana)}</b></td><td>${fmt(r.antes.p95)} → ${fmt(r.depois.p95)}</td><td>${fmt(r.antes.max)} → ${fmt(r.depois.max)}</td><td>${r.antes.cliques} → ${r.depois.cliques}</td><td>${fmt(r.reducao)}%</td></tr>`).join('');
const completos=[antes,depois,...extras];const verificacoes=completos.reduce((s,x)=>s+x.verificacoes.length,0),falhas=completos.flatMap(x=>x.falhas.map(f=>({...f,fase:x.fase}))),limpeza=completos.flatMap(x=>x.limpeza.map(f=>({...f,fase:x.fase})));
const itens=[
 ['Financeiro / contas','Cadastro, busca, filtro, edição, recebimento, pagamento, parcela, estorno e CSV','52 casos antes; matriz otimizada com interrupções na transição mensal, completadas no reteste; 20 processos por caso'],
 ['Formulário de conta','Atalho Salvar e receber/pagar; detalhes opcionais; validação de data recolhida','E2E dos 26 subsistemas e falhas controladas'],
 ['Formulário de baixa','Saldo, data, conta ativa, taxa, confirmação, troca de cartão para Pix','Parcial + quitação + saldo real; clique repetido e reenvio de chave'],
 ['Consulta e sincronização financeira','AbortSignal na busca; mantém campo/foco; bloqueia ações de lista antiga','Resposta de busca retida e histórico com atraso deliberado de 2,2 s'],
 ['Apuração completa','Exportações contábil e de caixa deixam de recalcular resultado após baixar arquivo','Download conferido e contagem das chamadas de apuração'],
 ['Contas mensais','Fixa, variável, informar valor e pausar; foco inicial; bloqueio da abertura de outro formulário enquanto uma operação termina','52 casos específicos repetidos após a correção, com resposta de pendências retida'],
 ['Contas bancárias','Consulta e transferência; correção do histórico em cache; estorno ao terminar','Saldo da origem e destino conferido antes/depois da limpeza'],
 ['Históricos dos indicadores','Resultado, receitas, custos, saldo, entradas e saídas','Consultas adicionais, com tempos separados'],
 ['Conciliação, custos, precificação, comissões e contratos','Revisão do código e abertura das consultas aplicáveis ao ramo','Não equivale a nova homologação de importação de extrato, pagamento de comissão ou emissão de contrato'],
 ['Integrações com OS, clientes e relatórios','Invalidação mantida; somente consultas da tela principal bloqueiam a confirmação','Backend e cálculos preservados; regressões financeiras listadas nos arquivos de validação'],
];
const controles=extras.filter(x=>['controle-antes','controle-depois-final'].includes(x.pasta));const controleRows=controles.flatMap(x=>[...new Set(x.resultados.map(r=>r.nome))].flatMap(nome=>[false,true].map(mobile=>{const a=stats(x.resultados.filter(r=>r.nome===nome&&r.mobile===mobile));return `<tr><td>${esc(x.fase)}</td><td>${a.n} amostras / ${mobile?'celular':'desktop'}</td><td>${esc(nome)}</td><td>${fmt(a.mediana)}</td><td>${a.consultas}</td></tr>`}))).join('');
const totais=extras.find(x=>x.pasta==='totais-depois');
const totaisConferidos=(totais?.verificacoes||[]).filter(v=>v.nome.startsWith('Total do histórico confere com resumo:')).length;
const geral=extras.filter(x=>x.pasta.startsWith('consultas-'));const geralRows=geral.flatMap(x=>[...new Set(x.resultados.map(r=>r.nome))].map(nome=>{const s=stats(x.resultados.filter(r=>r.nome===nome));return `<tr><td>${esc(x.fase)}</td><td>${esc(nome)}</td><td>${s.n}</td><td>${fmt(s.mediana)}</td><td>${fmt(s.p95)}</td><td>${fmt(s.max)}</td></tr>`})).join('');
const alternadas=extras.filter(x=>x.pasta.startsWith('alternado-'));
const alternadosRows=['antes','depois'].flatMap(versao=>[false,true].flatMap(mobile=>['Abrir financeiro','Cadastrar e receber uma conta','Cadastrar e pagar uma conta'].map(nome=>{
 const rows=alternadas.filter(x=>x.pasta.includes(versao)).flatMap(x=>x.resultados).filter(x=>x.mobile===mobile&&x.nome===nome),s=stats(rows);
 return '<tr><td>'+versao+'</td><td>'+(mobile?'Celular':'Desktop')+'</td><td>'+esc(nome)+'</td><td>'+s.n+'</td><td>'+fmt(s.mediana)+'</td><td>'+fmt(s.p95)+'</td><td>'+s.cliques+'</td></tr>';
}))).join('');
let validacoes='Consulte os arquivos de validação da pasta.';try{validacoes=await readFile(resolve(root,'validacoes-resumo.txt'),'utf8')}catch{}
const html=`<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Financeiro: velocidade e segurança dos registros</title><style>body{margin:0;background:#eef2f3;color:#17272d;font:15px/1.55 system-ui}main{max-width:1380px;margin:auto;padding:40px 24px}h1{font-size:36px;line-height:1.15}h2{margin-top:38px}section,.card{background:white;padding:24px;border-radius:14px;margin:18px 0}table{border-collapse:collapse;width:100%;font-size:13px}th,td{padding:11px 9px;border-bottom:1px solid #d7e1e3;text-align:left}th{background:#dceae9}tr:nth-child(even){background:#f3f7f7}.scroll{overflow:auto}a{color:#006763}.badge{background:#dceee7;padding:6px 12px;border-radius:18px}.muted{color:#50656d}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#eef2f3;padding:16px}code{overflow-wrap:anywhere}li{margin:8px 0}img{width:calc(100% - 18px);max-width:380px;vertical-align:top;margin:8px;border:1px solid #d1dddf;border-radius:8px}td,p,li{overflow-wrap:anywhere}@media(max-width:600px){main{padding:24px 12px}section{padding:16px}h1{font-size:28px}.scroll table{min-width:750px}section>table{display:block;overflow:auto;max-width:100%}}@media print{body{background:white}main{padding:0}section{padding:0}th{background:#ddd!important}.scroll{overflow:visible}table{font-size:9px}tr{break-inside:avoid}} </style><main>
<span class="badge">Auditoria financeira · 17/11/2026</span><h1>Menos passos para registrar dinheiro.<br>Valores conferidos do início ao fim.</h1>
<p><b>Entrega local validada com o Supabase conectado. Esta rodada não publicou na Vercel.</b> Os lançamentos foram feitos somente nas empresas fictícias identificadas para QA.</p>
<section><h2>O que mudou</h2><ul><li>Conta nova: <b>Salvar e receber</b> ou <b>Salvar e pagar</b> abre diretamente a confirmação, sem procurar a conta de novo. Os dois formulários pequenos acompanham a tela, evitando uma nova espera de carregamento, e as duas consultas posteriores à gravação executam em paralelo.</li><li>Data do resultado, pessoa e observações continuam disponíveis em detalhes opcionais. Data, saldo e conta válida já vêm preenchidos na baixa.</li><li>A busca mantém o foco durante a resposta do servidor e cancela consultas substituídas. Ações de linhas antigas ficam bloqueadas até a lista atual chegar.</li><li>Salvar aguarda o painel financeiro visível. Históricos e outras telas continuam sendo atualizados em segundo plano.</li><li>A troca de cartão para Pix limpa a taxa anterior. Pagamento duplicado continua protegido por trava na interface e chave única no servidor.</li><li>Exportar para o contador não dispara recálculo desnecessário da apuração.</li><li>Transferências e alterações de contas bancárias invalidam os históricos e relatórios, evitando exibir saldo anterior em cache.</li></ul></section>
<section><h2>Como os segundos foram medidos</h2><p>Mesmo computador, Chrome, uma execução por vez, frontend de produção servido localmente com proxy para o banco real. Desktop 1920 × 1080. Celular emulado 390 × 844, toque e CPU 4× mais lenta. Não é teste em aparelho físico nem inclui uma rede 4G simulada.</p><p>Tempo desde a primeira ação automatizada do processo até o resultado visível confirmado. Inclui navegação, consultas e gravações; <b>não inclui tempo humano de pensar ou digitar</b>. Há uma amostra por perfil/dispositivo/fase; a mediana e o P95 agregam 26 empresas, não 26 repetições da mesma empresa. Testes sequenciais sujeitos à variação da rede e do banco. O ambiente é compartilhado: os saldos retornam à base inicial, mas o histórico de auditoria dos testes permanece; não se trata de duas restaurações de um snapshot idêntico. As estatísticas de duração usam execuções concluídas. Tentativas com falha, incluindo a abertura que atingiu o limite de 25 s, ficam separadas nas ocorrências; não são convertidas em zero nem apagadas. Mediana é o ponto central das medições; P95 é o tempo dentro do qual 95% das amostras terminaram. Percentual negativo significa que ficou mais lento nessa medição.</p><p>Build anterior: <code>${esc(JSON.stringify(antes.build))}</code><br>Build da matriz otimizada: <code>${esc(JSON.stringify(depois.build))}</code><br>Build da entrega, com a proteção final das contas mensais: <code>${esc(JSON.stringify(buildEntrega))}</code></p></section>
<section><h2>Comparação dos 20 processos nos 26 subsistemas</h2><p>${antes.resultados.length} medições antes e ${depoisAnalise.length} depois: ${depois.resultados.length} da matriz otimizada e ${complemento.length} complementos do reteste após corrigir a transição das contas mensais. O ajuste final desses dois botões foi verificado novamente em 52 casos específicos; os demais processos mantêm o código já medido. Nenhuma amostra bem-sucedida foi trocada pelo tempo de um reteste. Busca e edição são apresentadas juntas, somando o tempo das duas etapas por caso: a nova lista continua visível durante a filtragem, por isso medir só a aparição da linha encerrava a busca antes de a resposta chegar. O total do processo completo evita essa distorção. Os registros individuais permanecem no CSV. “A/D” é quantidade antes/depois. Tempos em segundos; cliques representam cliques emitidos pelo roteiro, sem contar gestos de seleção do sistema operacional.</p><div class="scroll"><table><thead><tr><th>Processo</th><th>Dispositivo</th><th>A/D</th><th>Mediana antes → depois</th><th>P95 antes → depois</th><th>Máximo antes → depois</th><th>Cliques</th><th>Redução mediana</th></tr></thead><tbody>${linhas}</tbody></table></div></section>
<section><h2>Comparação alternada dos lançamentos mais usados</h2><p>Na matriz principal, nem toda mediana melhorou. Por isso, foram feitas quatro rodadas adicionais nos mesmos quatro ramos (retífica, assistência de celulares, manutenção de climatização e limpeza geral), em desktop e celular, na ordem anterior → intermediária → intermediária → anterior. A espera adicional identificada nessa comparação levou à última otimização: carregar os dois formulários pequenos junto da rota financeira e consultar a conta salva em paralelo com a atualização do painel. A matriz principal acima usa essa otimização. Depois, uma proteção de dois botões das contas mensais foi acrescentada e testada separadamente nos 26 subsistemas. É uma comparação complementar em janelas próximas, com 8 amostras por versão/dispositivo/processo. Não substitui os tempos originais dos 26 subsistemas. As etapas de cada cadastro estão registradas no JSON.</p><div class="scroll"><table><thead><tr><th>Versão</th><th>Dispositivo</th><th>Processo</th><th>Amostras</th><th>Mediana (s)</th><th>P95 (s)</th><th>Cliques</th></tr></thead><tbody>${alternadosRows}</tbody></table></div></section>
<section><h2>Correção da causa: atrasos e falhas deliberados</h2><p>A resposta do histórico foi atrasada 2,2 s para comprovar o desacoplamento. A resposta da busca foi retida para conferir foco e bloqueio de ações antigas. Também foram testados clique repetido, reenvio de chave, falha após salvar a conta, falha na baixa e recuperação sem duplicação. Os atrasos abaixo são artificiais e não entram nas estatísticas normais. A tabela mostra medianas por dispositivo; todos os casos individuais estão nos arquivos de evidência. O carregamento conjunto dos formulários acrescentou cerca de 2,2 kB compactados ao módulo financeiro e eliminou duas etapas de carregamento durante o registro. <a href="carregamento-formularios.json">Tamanhos dos módulos</a> e <a href="piloto-estatico/resultados.json">tempos por etapa na confirmação do ajuste</a>.</p><div class="scroll"><table><thead><tr><th>Fase</th><th>Perfil/dispositivo</th><th>Processo</th><th>Segundos</th><th>Consultas</th></tr></thead><tbody>${controleRows}</tbody></table></div></section>
<section><h2>Consultas financeiras adicionais</h2><p>Abertura com dados carregados das seções aplicáveis ao ramo. Estes tempos ficam separados das operações de lançamento. São medições da versão intermediária corrigida, anteriores à otimização final da passagem cadastro → baixa. As consultas e cálculos dessas seções permaneceram iguais; não há comparação anterior para elas.</p><div class="scroll"><table><thead><tr><th>Fase</th><th>Consulta</th><th>Amostras</th><th>Mediana (s)</th><th>P95 (s)</th><th>Máximo (s)</th></tr></thead><tbody>${geralRows}</tbody></table></div></section>
<section><h2>Conferência dos valores e rastreabilidade</h2><p>${verificacoes} verificações registradas nos roteiros, incluindo layout e saldos. Uma rodada específica, antes do último ajuste de carregamento dos formulários, confrontou os seis totais dos cartões com seus históricos em ${totais?.limpeza.length||0} combinações de subsistema/dispositivo: ${totaisConferidos} comparações. Na matriz principal, cada caso confere R$ 123,45 recebidos, R$ 88,90 pagos, baixa parcial de R$ 40,00 com taxa de R$ 2,00, quitação do restante, parcelamento de R$ 100,01 sem perder centavos, recorrências fixa e variável e transferência.</p><p>Ao terminar, os lançamentos próprios de QA são estornados/cancelados e as recorrências pausadas, preservando o histórico. Cada caso confere que os saldos por conta e o resumo financeiro voltaram exatamente à base inicial. ${limpeza.filter(l=>l.ok).length} encerramentos registrados como concluídos; ${limpeza.filter(l=>!l.ok).length} registrados com falha. Na interrupção de conexão, 28 casos falharam antes de criar qualquer registro e um caso em andamento exigiu recuperação, já conferida. As reproduções com falhas no roteiro também possuem encerramento ou arquivo de recuperação próprios.</p><pre>${esc(validacoes)}</pre></section>
<section><h2>Componentes revisados e limites da cobertura</h2><table><thead><tr><th>Parte</th><th>Revisão</th><th>Evidência / limite</th></tr></thead><tbody>${itens.map(x=>'<tr>'+x.map(y=>'<td>'+esc(y)+'</td>').join('')+'</tr>').join('')}</tbody></table><p>Não foi feita movimentação em banco externo, cobrança a clientes reais ou alteração das regras contábeis, permissões e autenticação. Os testes confirmam os cenários descritos; não representam garantia de ausência de todo bug possível.</p></section>
<section><h2>Interrupção de conexão e ocorrências durante a execução</h2><p>Uma rodada foi interrompida após 23 casos completos. O navegador e o cliente Node perderam a conexão; no intervalo de 13:34 a 13:38 UTC, os logs do Supabase consultados contêm 689 respostas 200/204, nenhuma 5xx, e tempo de origem máximo de 201 ms. O Windows registrou <b>Rede Desconectada às 10:36:12</b> e <b>Rede Conectada às 10:38:15</b> (horário de São Paulo), com nova oscilação às 10:38:51–58. A coincidência aponta para interrupção da conexão local; a causa física da desconexão não foi determinada. <a href="eventos-rede-windows.json">Eventos do Windows, sem identificação da rede</a>. Os dois registros fictícios do caso interrompido foram conferidos; o recebimento foi estornado e as contas canceladas. A rodada final usa arquivo separado. <a href="incidente-conexao.json">Evidência do incidente</a> e <a href="depois-26/encerramento-recuperado.json">recuperação conferida</a>.</p><p>Falhas de roteiro e retestes permanecem documentados, sem substituir as medições originais.</p><table><thead><tr><th>Fase</th><th>Perfil</th><th>Etapa</th><th>Ocorrência</th></tr></thead><tbody>${falhas.map(f=>`<tr><td>${esc(f.fase)}</td><td>${esc(f.perfil)}</td><td>${esc(f.etapa)}</td><td>${esc(f.erro).slice(0,900)}</td></tr>`).join('')||'<tr><td colspan="4">Nenhuma falha registrada.</td></tr>'}</tbody></table><p>Na rodada depois-final-26, a abertura da retífica no celular exibiu a proteção do aplicativo antes de qualquer lançamento. Houve outro evento de rede desconectada/conectada às 13:42:28–30 de São Paulo (<a href="eventos-rede-abertura.json">evidência</a>). O erro JavaScript original não foi capturado nessa execução; não é possível atribuí-lo conclusivamente apenas à rede. A sequência de aberturas com diagnóstico ampliado está em <a href="aberturas-diagnostico/resultados.json">aberturas-diagnostico</a>, e a repetição completa está em <a href="reteste-retifica/resultados.json">reteste-retifica</a>. As 24 aberturas adicionais e os 40 processos dos dois dispositivos passaram, sem reproduzir o erro. Isso não prova a causa do erro original nem autoriza afirmar ausência de todas as falhas.</p><p>O primeiro controle-antes-piloto também foi interrompido por uma resposta de rede já liberada no capturador; <a href="controle-antes-piloto/encerramento-recuperado.json">a conta fictícia foi encerrada e conferida</a>. Os seis erros em cache-depois ocorreram porque o roteiro lia antes da navegação ou da filtragem terminar; os oito casos foram encerrados e repetidos em cache-depois-final.</p><p>O piloto antes-3 encerrou o processo por interpretar como JSON uma resposta vazia (204). O capturador foi corrigido; <a href="piloto-antes-3/encerramento-recuperado.json">a recuperação dos seus registros foi conferida separadamente</a>.</p></section>
<section><h2>Correção da transição de contas mensais</h2><p>Nos casos de ${[...new Set(depois.falhas.map(x=>x.perfil))].map(x=>esc(x.replaceAll("_"," "))).join(", ")}, após pausar uma conta, o estado “Retomar” já aparecia enquanto outra consulta de pendências ainda terminava. O botão “Nova conta mensal” permitia abrir um formulário nesse intervalo; ao concluir a pausa, o código fechava o formulário recém-aberto. Não houve divergência de valores, e os registros do caso foram encerrados.</p><p>A reprodução controlada reteve a resposta de pendências, confirmando o fechamento indevido. A correção bloqueia “Nova conta mensal” e “Informar valor” durante a operação, com uma trava adicional no manipulador. Foram repetidos os fluxos mensal fixo, variável, informação de valor e pausa nas 52 combinações de subsistema e dispositivo, além dos casos completos interrompidos. <a href="mensais-reproducao/resultados.json">Reprodução antes da proteção</a>, <a href="mensais-corrigidos-26/resultados.json">validação após a proteção</a> e <a href="reteste-otimizado/resultados.json">retestes completos dos casos interrompidos</a>.</p></section>
<section><h2>Formulário no celular</h2><p>Antes, campos adicionais ocupavam a tela inicial. Depois, parcelamento e detalhes continuam opcionais, e a confirmação de pagamento é aberta diretamente pelo cadastro.</p><a href="controle-antes/retifica-celular-cadastro.png"><img alt="Cadastro anterior no celular" src="controle-antes/retifica-celular-cadastro.png"></a><a href="controle-depois-final/retifica-celular-cadastro.png"><img alt="Cadastro corrigido no celular" src="controle-depois/retifica-celular-cadastro.png"></a><a href="controle-depois-final/retifica-celular-pagamento.png"><img alt="Confirmação de pagamento no celular" src="controle-depois/retifica-celular-pagamento.png"></a></section><section><h2>Arquivos de evidência</h2><ul><li><a href="tempos-detalhados.csv">Todos os tempos, cliques e consultas por perfil</a></li><li><a href="resumo.json">Resumo comparativo em JSON</a></li><li><a href="alteracoes.patch">Alterações exatas em relação ao início da tarefa</a></li><li><a href="arquivos-alterados.json">Arquivos alterados e hashes</a></li><li><a href="validacoes-resumo.txt">Compilação, regressões de banco e interface</a></li>${completos.map(x=>`<li><a href="${esc(x.fase)}/resultados.json">${esc(x.fase)}: medições, verificações, rede e encerramentos</a></li>`).join('')}</ul><p><a href="cache-antes/resultados.json">Reprodução do saldo em cache</a> e <a href="cache-depois-final/resultados.json">oito validações da correção em quatro ramos, desktop e celular</a>. Capturas de formulários e detalhes estão nas pastas das execuções. Nenhuma senha ou token é incluído no relatório.</p></section></main></html>`;
await writeFile(resolve(root,'relatorio.html'),html);
